# Audit host only: POMs that declare Central under their own repository id (public, repo1, ...)
# bypass the id-based <mirror> and hit rate-limited Central directly. Offering the local mirror as
# an extra repository covers them regardless of id: whatever Central refuses is served here.
WSO2_PUBLIC = 'https://maven.wso2.org/nexus/content/groups/wso2-public/'


def _fallback_profile(central: str | None) -> str:
    """Repositories consulted after the POM's own: whatever the declared repositories no longer
    serve is looked up here, whatever repository id the POM happened to use."""
    repos = [('fallback-wso2', WSO2_PUBLIC)] + ([('audit-proxy-central', central)] if central else [])
    entry = ('        <{tag}><id>{id}</id><url>{url}</url>\n'
             '          <releases><enabled>true</enabled></releases>'
             '<snapshots><enabled>false</enabled></snapshots></{tag}>\n')
    body = ''.join(entry.format(tag='repository', id=i, url=u) for i, u in repos)
    plugins = ''.join(entry.format(tag='pluginRepository', id=i + '-plugins', url=u) for i, u in repos)
    return ('  <profiles>\n    <profile>\n      <id>inferredbugs-fallbacks</id>\n'
            '      <repositories>\n' + body + '      </repositories>\n'
            '      <pluginRepositories>\n' + plugins + '      </pluginRepositories>\n'
            '    </profile>\n  </profiles>\n'
            '  <activeProfiles><activeProfile>inferredbugs-fallbacks</activeProfile></activeProfiles>\n')


def maven_settings(central: str, restlet: str, jenkins: str, proxy_central: bool) -> str:
    mirrors = ('    <mirror><id>audit-central-proxy</id><mirrorOf>central</mirrorOf><url>%s</url></mirror>\n' % central
               if proxy_central else '')
    fallback = _fallback_profile(central if proxy_central else None)
    return ('<settings xmlns="http://maven.apache.org/SETTINGS/1.0.0">\n  <mirrors>\n' + mirrors
            + _MIRRORS_COMMON.format(restlet=restlet, jenkins=jenkins, central=central) + '  </mirrors>\n'
            + fallback + '</settings>\n')


# Portable settings shipped inside tasks: public hosts only.
PORTABLE_SETTINGS = maven_settings('https://repo.maven.apache.org/maven2', 'https://maven.restlet.talend.com',
                                   'https://repo.jenkins-ci.org/public', proxy_central=False)


def audit_settings(args) -> str:
    if args.maven_proxy:
        p = args.maven_proxy.rstrip('/')
        return maven_settings(p + '/maven2', p + '/restlet', p + '/jenkins', proxy_central=True)
    return PORTABLE_SETTINGS


# Audit-host only: Maven's resolver sleeps and retries when a repository answers 429/503.
# Central rate-limits this host (dozens of parallel builds), and POM-declared Central clones are
# not covered by the id-based <mirror>, so every artifact burned seconds in retry sleeps before
# falling through to the local proxy. Fail those transfers fast instead; the next repository in
# the list (our mirror) serves the artifact. Packaged tasks keep Maven's defaults.
AUDIT_MAVEN_OPTS = ('-Daether.connector.http.retryHandler.count=0 '
                    '-Dmaven.wagon.http.retryHandler.count=0 '
                    '-Daether.connector.connectTimeout=15000 '
                    '-Dmaven.wagon.http.connectionTimeout=15000')


# --------------------------------------------------------------------------- small helpers
def cache_files(root: Path) -> set:
    """Files under a cache directory; tolerant of directories vanishing mid-walk."""
    out = set()
    for directory, _, names in os.walk(root, onerror=lambda e: None):
        for n in names:
            out.add(Path(directory) / n)
    return out


def broken_nuget_reason(package: Path) -> str | None:
    """Why a package counts as half extracted (for the log), or None when it is fine."""
    for assets in ('lib', 'ref', 'build', 'runtimes'):
        tree = package / assets
        if tree.is_dir() and any(tree.iterdir()) and not any(f.is_file() for f in tree.rglob('*')):
            return f'{assets}/ tree holds no file at all'
    for assets in ('lib', 'ref', 'build', 'runtimes'):
        for directory in (package / assets).rglob('*') if (package / assets).is_dir() else ():
            if directory.is_dir() and not any(directory.iterdir()):
                return f'empty {directory.relative_to(package)}'
    for tree in package.rglob('*'):
        if not tree.is_dir():
            continue
        parts = tree.relative_to(package).parts
        if not (parts[0] in ('lib', 'ref') or (parts[0] == 'build' and 'ref' in parts)):
            continue
        files = [f for f in tree.iterdir() if f.is_file()]
        if files and not any(f.suffix.lower() in ('.dll', '.exe', '.winmd') or f.name == '_._' for f in files):
            return f'{tree.relative_to(package)} has {", ".join(sorted(f.name for f in files)[:3])} but no assembly'
    return None


def broken_nuget_package(package: Path) -> bool:
    """A NuGet package extracted only in part: the completion marker is there, the assemblies are
    not. Every later restore then reports the package as incompatible with the target framework or
    loses the framework's reference assemblies entirely."""
    for assets in ('lib', 'ref', 'build', 'runtimes'):
        tree = package / assets
        if tree.is_dir() and any(tree.iterdir()) and not any(f.is_file() for f in tree.rglob('*')):
            return True
    for assets in ('lib', 'ref', 'build', 'runtimes'):
        for directory in (package / assets).rglob('*') if (package / assets).is_dir() else ():
            # An asset tree has no empty directories: one means its files were lost. NuGet then
            # reads the framework as "present but empty" and reports the package as incompatible.
            # (Elsewhere an empty directory is normal: old packages leave an empty OPC `_rels/`.)
            if directory.is_dir() and not any(directory.iterdir()):
                return True
    for tree in package.rglob('*'):
        if not tree.is_dir():
            continue
        parts = tree.relative_to(package).parts
        # the package's own lib/ and ref/ trees, and the reference assemblies a targeting pack
        # ships under build/<tfm>/ref/. Everything else (native payloads, MSBuild tasks) is free
        # to hold whatever it likes.
        if not (parts[0] in ('lib', 'ref') or (parts[0] == 'build' and 'ref' in parts)):
            continue
        files = [f for f in tree.iterdir() if f.is_file()]
        if files and not any(f.suffix.lower() in ('.dll', '.exe', '.winmd') or f.name == '_._' for f in files):
            return True
    return False


def purge_packages_named_in(log: Path, dep_cache: Path) -> list:
    """Packages a failed build itself points at: a file it could not copy out of the cache
    (MSB3030), or one NuGet called incompatible because its assemblies never arrived (NU1202).
    Structural checks cannot see every shape of damage; the build's own message can."""
    try:
        text = log.read_text(errors='replace')
    except OSError:
        return []
    targets = {f'{m.group(1)}/{m.group(2)}' for m in
               re.finditer(r'/cache/nuget/([\w.\-]+)/([\w.\-+]+)/', text)
               if 'MSB3030' in text[max(0, m.start() - 300):m.start()]}
    targets |= {f'{m.group(1).lower()}/{m.group(2)}' for m in
                re.finditer(r'Package ([\w.\-]+) ([\w.\-+]+) is not compatible', text)}
    removed = []
    for target in sorted(targets):
        package = dep_cache / 'nuget' / target
        if package.is_dir():
            shutil.rmtree(package, ignore_errors=True); removed.append(target)
    return removed


def purge_broken_nuget(dep_cache: Path) -> list:
    """Drop half-extracted packages from a shared cache so NuGet fetches them again. Every version
    directory is inspected, including ones whose completion marker never got written."""
    removed = []
    for package in Path(dep_cache, 'nuget').glob('*/*'):
        if not package.is_dir():
            continue
        reason = broken_nuget_reason(package)
        if reason:
            shutil.rmtree(package, ignore_errors=True); removed.append(f'{package.parent.name} {package.name} ({reason})')
    return removed


PROJECT_LOCKS: dict = collections.defaultdict(threading.Lock)
PROJECT_LOCKS_GUARD = threading.Lock()


def project_lock(language: str, project: str) -> threading.Lock:
    """Tasks of one project share a dependency cache, so they are validated one at a time."""
    with PROJECT_LOCKS_GUARD:
        return PROJECT_LOCKS[(language, project)]


def sha(path) -> str:
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()


def records(path):
    p = Path(path)
    return [json.loads(l) for l in p.read_text().splitlines() if l.strip()] if p.exists() else []


def dump(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + '.tmp')
    tmp.write_text(json.dumps(value, indent=2, default=str) + '\n'); tmp.replace(path)


def digest(value) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, default=str).encode()).hexdigest()


def canonical_source(text: str) -> str:
    return text.removeprefix('\ufeff').replace('\r\n', '\n').replace('\r', '\n')


def digest_text(text: str) -> str:
    return hashlib.sha256(canonical_source(text).encode('utf-8')).hexdigest()


def source_digest(path: Path) -> str:
    return digest_text(Path(path).read_bytes().decode('utf-8-sig', errors='replace'))


def lossy_text(data: bytes) -> str:
    """ASCII-only projection: some dataset copies were saved with undecodable bytes dropped."""
    return re.sub(r'[^\x00-\x7f]', '', canonical_source(data.decode('utf-8', errors='replace')))


def safe_path(name: str) -> str:
    p = PurePosixPath(name)
    if p.is_absolute() or '..' in p.parts or not p.parts:
        raise ValueError(f'Unsafe repository path: {name!r}')
    return str(p)


def unpack(blob: bytes) -> dict:
    out = {}
    with tarfile.open(fileobj=io.BytesIO(blob), mode='r:*') as t:
        for m in t:
            if m.isfile():
                out[m.name.removeprefix('./')] = t.extractfile(m).read()
    return out


def pack(files: dict) -> bytes:
    b = io.BytesIO()
    with tarfile.open(fileobj=b, mode='w:gz') as t:
        for name, data in files.items():
            x = tarfile.TarInfo(name); x.size = len(data); x.mode = 0o755 if name.endswith('.sh') else 0o644
            t.addfile(x, io.BytesIO(data))
    return b.getvalue()


# --------------------------------------------------------------------------- matching
def _field(instruction, label):
    m = re.search(rf'^\*\*{re.escape(label)}:\*\*\s*(.*?)\s*$', instruction, re.M)
    return m.group(1) if m else None


def _section(instruction, label):
    m = re.search(rf'^### {re.escape(label)}:\s*\n(.*?)(?=\n(?:### |## )|\Z)', instruction, re.M | re.S)
    return m.group(1).strip() if m else None


def parse_instruction(instruction: str) -> dict:
    src = re.search(r'\*\*Before \(Buggy File\):\*\*\s*\n```[^\n]*\n(.*?)\n```', instruction, re.S)
    return {'language': (_field(instruction, 'Language') or '').lower(), 'project': _field(instruction, 'Project'),
            'bug_id': _field(instruction, 'Bug ID'), 'file_before': src.group(1) if src else None,
            'bug_class': _section(instruction, 'Bug Class'), 'bug_type': _section(instruction, 'Bug Type'),
            'qualifier': _section(instruction, 'Qualifier'), 'target_file': _section(instruction, 'File'),
            'procedure': _section(instruction, 'Procedure')}


def original_records(root: Path) -> list:
    out = []
    for language in ('java', 'csharp'):
        for bug_json in (root / 'inferredbugs' / language).glob('*/*/bug.json'):
            d = bug_json.parent
            if not (d / 'file_before.txt').exists():
                continue
            meta = json.loads(bug_json.read_text(encoding='utf-8'))
            out.append({'language': language, 'project': d.parent.name, 'bug_id': d.name, 'record_dir': str(d),
                        'file_before_sha256': digest_text((d / 'file_before.txt').read_text(encoding='utf-8')),
                        'has_file_after': (d / 'file_after.txt').exists(), 'bug_type': meta.get('bug_type'),
                        'qualifier': meta.get('qualifier'), 'target_file': meta.get('file'), 'procedure': meta.get('procedure')})
    return out


def match_dataset(parquet: Path, ib_root: Path) -> list:
    """Deterministic match of TaskTrove rows to original records: language+project+bug id,
    validated by the SHA-256 of the buggy file embedded in instruction.md."""
    originals = original_records(ib_root)
    by_identity = collections.defaultdict(list); by_source = collections.defaultdict(list)
    for r in originals:
        by_identity[(r['language'], r['project'], r['bug_id'])].append(r)
        by_source[(r['language'], r['file_before_sha256'])].append(r)
    results = []
    for row in pq.read_table(parquet, columns=['path', 'task_binary']).to_pylist():
        parsed = parse_instruction(unpack(row['task_binary'])['instruction.md'].decode('utf-8', errors='replace'))
        source_hash = digest_text(parsed['file_before']) if parsed['file_before'] is not None else None
        candidates = by_identity.get((parsed['language'], parsed['project'], parsed['bug_id']), [])
        exact = [c for c in candidates if c['file_before_sha256'] == source_hash]
        if len(exact) == 1:
            status, matched = 'unique', exact[0]
        elif not candidates and source_hash:
            sc = by_source.get((parsed['language'], source_hash), [])
            status = 'unique_source_only' if len(sc) == 1 else 'ambiguous' if sc else 'unmatched'
            matched = sc[0] if len(sc) == 1 else None
        elif len(exact) > 1 or len(candidates) > 1:
            status, matched = 'ambiguous', None
        else:
            status, matched = 'source_mismatch', None
        result = {'tasktrove_task': row['path'], 'status': status, 'file_before_sha256': source_hash,
                  'parsed': {k: v for k, v in parsed.items() if k != 'file_before'}}
        if matched:
            result['original'] = matched
        results.append(result)
    return results


# --------------------------------------------------------------------------- git / GitHub
def github_token(args=None) -> str | None:
    if args is not None and args.token_file:
        return args.token_file.read_text().strip()
    for key in ('GITHUB_TOKEN', 'GH_TOKEN'):
        if os.environ.get(key):
            return os.environ[key].strip()
    try:
        return Path(os.path.expanduser('~/.github_api_token')).read_text().strip() or None
    except OSError:
        return None


def git_environment(env: dict, token: str | None) -> dict:
    """Scoped Authorization header for github.com via GIT_CONFIG_* (never argv or config files)."""
    env = dict(env, GIT_TERMINAL_PROMPT='0', GIT_ASKPASS='/bin/false')
    if token:
        auth = base64.b64encode(('x-access-token:' + token).encode()).decode()
        i = int(env.get('GIT_CONFIG_COUNT', '0'))
        env[f'GIT_CONFIG_KEY_{i}'] = 'http.https://github.com/.extraheader'
        env[f'GIT_CONFIG_VALUE_{i}'] = 'Authorization: Basic ' + auth
        env[f'GIT_CONFIG_KEY_{i+1}'] = 'credential.helper'; env[f'GIT_CONFIG_VALUE_{i+1}'] = ''
        env['GIT_CONFIG_COUNT'] = str(i + 2)
    return env


TOKEN: str | None = None
CLONE_SLOTS = threading.BoundedSemaphore(int(os.environ.get('IB_CLONE_SLOTS', '8')))


def run_process(args, *, cwd=None, timeout=300, input_text=None, log_path=None):
    env = None
    if args and args[0] == 'git':
        args = ['git', '-c', 'credential.helper=', '-c', 'core.askPass=/bin/false', *args[1:]]
        env = git_environment(os.environ, TOKEN)
    started = time.monotonic()
    try:
        proc = subprocess.run(args, cwd=cwd, input=input_text, text=True, stdout=subprocess.PIPE,
                              stderr=subprocess.STDOUT, timeout=timeout, env=env)
        code, output = proc.returncode, proc.stdout
    except subprocess.TimeoutExpired as e:
        code, output = None, (e.stdout or '') + f'\nTIMEOUT after {timeout}s\n'
    if log_path:
        Path(log_path).parent.mkdir(parents=True, exist_ok=True)
        Path(log_path).write_text(output, encoding='utf-8')
    return code, output, time.monotonic() - started


@dataclass(frozen=True)
class Task:
    task_id: str
    language: str
    project: str
    bug_id: str
    record_dir: Path
    commit: str
    target_file: str
    file_after_sha256: str
    repository: str
    file_before_sha256: str = ''
    parent: str = ''          # the fixing commit's parent: the tree the task is built from
    # 'parent': the buggy tree is the fixing commit's parent (the state the developer fixed).
    # 'fix-commit': the parent does not compile with any recipe (a broken intermediate commit),
    # so the task stands on the fixing commit with only the target reverted to its buggy version.
    environment: str = 'parent'


ENVIRONMENTS = ('parent', 'fix-commit')


def base_commit(task: Task) -> str:
    """The commit a task's checkout is reset to: the parent of the fix (the buggy tree) or, for
    a task whose parent commit does not build, the fixing commit itself."""
    return task.parent if task.environment == 'parent' and task.parent else task.commit


def prepare_checkout(task: Task, checkout: Path, log_path: Path) -> bool:
    """Shallow clone of the fixing commit with its parent, checked out AT THE PARENT: the fix
    commit usually changes other files too (84% of them do), so only the parent tree is a coherent
    buggy state. Repository-side .gitattributes may expand $Id$ keywords or rewrite line endings;
    the dataset's file_before/after.txt are the raw blobs."""
    if checkout.exists():
        shutil.rmtree(checkout)
    checkout.parent.mkdir(parents=True, exist_ok=True)
    commands = [['git', 'init', '-q', str(checkout)],
                ['git', '-C', str(checkout), 'remote', 'add', 'origin', f'https://github.com/{task.repository}.git'],
                ['git', '-C', str(checkout), 'fetch', '-q', '--depth=2', 'origin', task.commit],
                ['git', '-C', str(checkout), 'checkout', '-q', '--detach', 'FETCH_HEAD^']]
    combined = []
    with CLONE_SLOTS:
        for i, command in enumerate(commands):
            if i == 1:
                info = checkout / '.git' / 'info'; info.mkdir(parents=True, exist_ok=True)
                (info / 'attributes').write_text('* -ident -text -eol\n')
            for attempt in range(4):
                code, output, _ = run_process(command, timeout=300)
                combined.append('$ ' + ' '.join(shlex.quote(x) for x in command) + '\n' + output)
                # a throttled or flaky fetch ("could not read Username", "expected flush", RPC
                # failed) is retried with a growing pause; a missing commit fails the same way
                # every time and costs three short waits
                if code == 0 or i != 2 or attempt == 3:
                    break
                time.sleep(20 * (attempt + 1) + random.randint(0, 10))
            if code != 0:
                Path(log_path).parent.mkdir(parents=True, exist_ok=True)
                Path(log_path).write_text('\n'.join(combined)); return False
    Path(log_path).parent.mkdir(parents=True, exist_ok=True); Path(log_path).write_text('\n'.join(combined))
    return True


class GitHub:
    def __init__(self, cache: Path, token: str | None):
        self.cache = cache; self.cache.mkdir(parents=True, exist_ok=True); self.token = token; self.last_search = 0.0

    def get(self, endpoint: str):
        cache_path = self.cache / (hashlib.sha256(endpoint.encode()).hexdigest() + '.json')
        if cache_path.exists():
            saved = json.loads(cache_path.read_text())
            if saved['status'] in (200, 404, 422):
                return saved['status'], saved.get('data')
        if endpoint.startswith('/search/'):
            time.sleep(max(0, 6.2 - (time.monotonic() - self.last_search))); self.last_search = time.monotonic()
        headers = {'Accept': 'application/vnd.github+json', 'User-Agent': 'OpenThoughts-InferredBugs-patcher',
                   'X-GitHub-Api-Version': '2022-11-28'}
        if self.token:
            headers['Authorization'] = f'Bearer {self.token}'
        try:
            with urllib.request.urlopen(urllib.request.Request(API + endpoint, headers=headers), timeout=30) as r:
                status, data = r.status, json.loads(r.read())
        except urllib.error.HTTPError as e:
            status = e.code
            try:
                data = json.loads(e.read())
            except Exception:
                data = None
            if status in (403, 429):
                reset = e.headers.get('X-RateLimit-Reset')
                wait = int(reset) - int(time.time()) + 2 if reset and reset.isdigit() else 0
                if 0 < wait <= 65:
                    time.sleep(wait); return self.get(endpoint)
                raise RuntimeError(f'GitHub API rate limit reached; reset={reset}') from e
        if status not in (200, 404, 422):
            raise RuntimeError(f'GitHub request failed: HTTP {status}')
        cache_path.write_text(json.dumps({'status': status, 'data': data}))
        return status, data


class GitHistory:
    """Verify that a repository serves the exact fixing commit and its parent, and that the
    target blob matches file_after.txt (exactly, or modulo undecodable bytes)."""
    def __init__(self, cache: Path):
        self.cache = cache

    def verify(self, repository: str, record: dict) -> tuple[bool, str]:
        if not re.fullmatch(r'[\w.-]+/[\w.-]+', repository):
            return False, 'invalid_repository'
        repo = self.cache / repository.replace('/', '__')
        def git(*a):
            code, out, _ = run_process(['git', '-C', str(repo), *a], timeout=600)
            if code != 0:
                raise ValueError('git_command_failed:' + a[0])
            return out
        try:
            if not repo.exists():
                repo.mkdir(parents=True); git('init', '--bare', '-q')
                git('remote', 'add', 'origin', 'https://github.com/' + repository + '.git')
            def history():
                body = git('cat-file', '-p', record['commit'])
                parents = re.findall(r'^parent ([0-9a-f]{40})$', body, re.M)
                if not parents:
                    raise ValueError('parent_missing')
                git('cat-file', '-e', parents[0] + '^{tree}')
            try:
                history()
            except ValueError:
                git('fetch', '-q', '--no-tags', '--filter=blob:none', '--depth=2', 'origin', record['commit']); history()
            source = git('show', record['commit'] + ':' + record['target_file'])
            if digest_text(source) == record['file_after_sha256']:
                return True, 'verified'
            after = Path(record['file_after_path']).read_bytes()
            if lossy_text(after) == lossy_text(source.encode('utf-8', 'replace')):
                return True, 'verified:lossy_encoding'
            return False, 'content_mismatch'
        except ValueError as e:
            return False, str(e)


PROJECT_REPOSITORY_HINTS = {('csharp', 'IfcDoc'): ('DongwanCho/IfcDoc',), ('java', 'SikuliX-2014'): ('niknah/SikuliX-2014',),
                            ('java', 'UA-Java-Legacy'): ('tosuns/UA-Java',), ('java', 'brpc-java'): ('baidu/starlight',)}


def _search(github, endpoint):
    for page in range(1, 11):
        status, data = github.get(endpoint + '&page=' + str(page))
        if status != 200:
            return
        items = data.get('items', [])
        for item in items:
            repo = item.get('repository', item).get('full_name')
            if repo:
                yield repo
        if len(items) < 100 or page * 100 >= data.get('total_count', 0):
            return


def _forks(github, repository: str, pages: int = 4):
    """The rest of a repository's fork network, newest fork first. The mapped repository is often
    itself a fork, so the search starts at the network root: that is where the other forks are."""
    if not re.fullmatch(r'[\w.-]+/[\w.-]+', repository or ''):
        return
    status, data = github.get(f'/repos/{repository}')
    if status == 200 and isinstance(data, dict) and data.get('fork'):
        root = (data.get('source') or data.get('parent') or {}).get('full_name')
        if root and root != repository:
            yield root
            repository = root
    for page in range(1, pages + 1):
        status, data = github.get(f'/repos/{repository}/forks?per_page=100&sort=newest&page={page}')
        if status != 200 or not isinstance(data, list):
            return
        for item in data:
            if item.get('full_name'):
                yield item['full_name']
        if len(data) < 100:
            return


def resolve_project(github, verify, language, project, recs, previous=None):
    previous = previous or {}
    saved = {r['tasktrove_task']: r for r in previous.get('tasks', [])}
    known = list(PROJECT_REPOSITORY_HINTS.get((language, project), ()))
    for name in [previous.get('repository'), *[r.get('repository') for r in saved.values()]]:
        if name and name not in known:
            known.append(name)
    results = []
    for record in recs:
        old = saved.get(record['tasktrove_task'], {})
        if (previous.get('schema_version') == 2 and old.get('status') == 'verified' and old.get('repository')
                and all(old.get(k) == record.get(k) for k in ('tasktrove_task', 'commit', 'target_file', 'file_after_sha256'))):
            results.append(old); continue
        result = dict(record, status='unresolved', repository=None, attempts=[])
        if not re.fullmatch(r'[0-9a-fA-F]{40}', record['commit'] or '') or not record['target_file']:
            result['reason'] = 'missing_commit_or_path'; results.append(result); continue
        tried = set()
        def attempt(candidates):
            for repository in candidates:
                if repository in tried:
                    continue
                tried.add(repository)
                valid, reason = verify(repository, record)
                result['attempts'].append({'repository': repository, 'status': reason})
                if valid:
                    result.update(status='verified', repository=repository)
                    if repository not in known:
                        known.insert(0, repository)
                    return True
            return False
        if not attempt(list(known)):
            q = '/search/commits?' + urllib.parse.urlencode({'q': record['commit'], 'per_page': 100})
            if not attempt(_search(github, q)):
                for name in dict.fromkeys([project, *[r.rsplit('/', 1)[-1] for r in known]]):
                    q = '/search/repositories?' + urllib.parse.urlencode({'q': name + ' in:name', 'sort': 'stars', 'per_page': 100})
                    if attempt(_search(github, q)):
                        break
        results.append(result)
    count = sum(r['status'] == 'verified' for r in results)
    return {'schema_version': 2, 'language': language, 'project': project, 'task_count': len(recs),
            'verified_task_count': count, 'status': 'all_tasks_verified' if count == len(recs) else 'partially_verified' if count else 'unresolved',
            'repository': next((r['repository'] for r in results if r['repository']), None), 'tasks': results}


def task_records_by_project(matches: list) -> dict:
    projects = collections.defaultdict(list)
    for m in matches:
        if 'original' not in m:
            continue
        o = m['original']; d = Path(o['record_dir'])
        projects[(o['language'], o['project'])].append({
            'tasktrove_task': m['tasktrove_task'], 'bug_id': o['bug_id'],
            'commit': json.loads((d / 'commit_info.json').read_text()).get('hash', ''),
            'target_file': json.loads((d / 'bug.json').read_text()).get('file'),
            'file_after_sha256': digest_text((d / 'file_after.txt').read_text(encoding='utf-8')),
            'file_after_path': str(d / 'file_after.txt')})
    for recs in projects.values():
        recs.sort(key=lambda r: (int(r['bug_id']) if str(r['bug_id']).isdigit() else 10**12, str(r['bug_id'])))
    return projects


def resolve_all(matches: list, output: Path, cache: Path, token: str | None):
    """Resume-able per-task repository resolution (schema 2 rows per project)."""
    github = GitHub(cache / 'api', token); history = GitHistory(cache / 'git')
    completed = {(r['language'], r['project']): r for r in records(output)}
    projects = task_records_by_project(matches)
    with output.open('a', encoding='utf-8') as out:
        for i, ((language, project), recs) in enumerate(sorted(projects.items()), 1):
            prev = completed.get((language, project), {})
            if prev.get('schema_version') == 2 and prev.get('verified_task_count') == len(recs) and \
               {r['tasktrove_task'] for r in prev['tasks']} == {r['tasktrove_task'] for r in recs}:
                continue
            result = resolve_project(github, history.verify, language, project, recs, prev)
            out.write(json.dumps(result, ensure_ascii=False) + '\n'); out.flush(); completed[(language, project)] = result
            print(f'[resolve {i}/{len(projects)}] {language}/{project}: {result["verified_task_count"]}/{len(recs)}', flush=True)
    output.write_text(''.join(json.dumps(r) + '\n' for _, r in sorted(completed.items())))


def load_tasks(matches: list, repositories: Path) -> dict:
    resolution = {(r['language'], r['project']): r for r in records(repositories)}
    projects = collections.defaultdict(list)
    for row in matches:
        if 'original' not in row:
            continue
        o = row['original']; key = (o['language'], o['project']); d = Path(o['record_dir'])
        commit = json.loads((d / 'commit_info.json').read_text()).get('hash', '')
        target = json.loads((d / 'bug.json').read_text()).get('file') or o.get('target_file') or ''
        after = source_digest(d / 'file_after.txt')
        res = resolution.get(key, {})
        if res.get('schema_version') == 2:
            r = next((t for t in res.get('tasks', []) if t['tasktrove_task'] == row['tasktrove_task']), {})
            repository = r.get('repository') if r.get('status') == 'verified' and (r.get('commit'), r.get('target_file'), r.get('file_after_sha256')) == (commit, target, after) else None
        else:
            repository = res.get('repository') if res.get('status') == 'unique_verified' else None
        if repository:
            projects[key].append(Task(row['tasktrove_task'], key[0], key[1], str(o['bug_id']), d, commit, target, after, repository,
                                      file_before_sha256=source_digest(d / 'file_before.txt')))
    return projects


# --------------------------------------------------------------------------- images
def resolve_image(tag: str | None, language: str) -> str:
    tag = DIGEST_IMAGES.get(tag or '', tag or '')
    tag = IMAGE_ALIASES.get(tag, tag)
    if tag in IMAGES:
        return tag
    return 'inferredbugs-java:8' if language == 'java' else 'inferredbugs-dotnet:8'


# The vendor dataset's dotnet8-full-microsoft-refs.dockerfile, embedded so the image never loses it.
# Without it /opt/ib-frameworks is missing and .NET Framework projects (RestSharp, Mongo2Go, ...) fail.
MICROSOFT_REFS_STEP = '# Microsoft .NET Framework reference assemblies for /opt/ib-frameworks (recovered from image history)\nRUN printf %s  | base64 -d | python3'


def dockerfile_text(tag: str, vendor_dir: Path | None) -> str:
    text = IMAGES[tag]
    if '{microsoft_refs}' in text:
        extra = (vendor_dir / 'dotnet8-full-microsoft-refs.dockerfile') if vendor_dir else None
        text = text.replace('{microsoft_refs}', extra.read_text().strip() if extra and extra.exists() else MICROSOFT_REFS_STEP)
    return text


def ensure_image(tag: str, cache: Path, vendor_dir: Path | None) -> str:
    """Build the image locally if missing; return its immutable id."""
    code, out, _ = run_process(['docker', 'image', 'inspect', '--format', '{{.Id}}', tag], timeout=30)
    if code != 0:
        with (cache / f'image-{tag.replace(":", "_")}.log').open('w') as log:
            proc = subprocess.run(['docker', 'build', '-q', '-t', tag, '-'], input=dockerfile_text(tag, vendor_dir),
                                  text=True, stdout=log, stderr=subprocess.STDOUT, timeout=3600)
        if proc.returncode:
            raise ValueError(f'Cannot build image {tag}; see {log.name}')
        code, out, _ = run_process(['docker', 'image', 'inspect', '--format', '{{.Id}}', tag], timeout=30)
    return out.strip()


# --------------------------------------------------------------------------- build execution
BUILD_SLOTS: threading.BoundedSemaphore | None = None
# Every packaged check starts by cloning from GitHub, which throttles bursts of anonymous
# fetches, so fewer of them run at once than ordinary builds.
CHECK_SLOTS: threading.BoundedSemaphore | None = None


def execute(root: Path, target: str, cache: Path, image: str, command: str, log: Path, timeout: int, cpus: int, memory: str):
    """Run a shell command inside the compiler image: checkout at /workspace (target read-only),
    private dependency cache at /cache, resource-limited, no docker socket or host secrets."""
    name = 'ib-build-' + hashlib.sha256((str(log) + str(time.time_ns())).encode()).hexdigest()[:12]
    for part in ('m2', 'gradle', 'nuget'):
        (cache / part).mkdir(parents=True, exist_ok=True)
    args = ['docker', 'run', '--rm', '--name', name, '--cpus', str(cpus), '--memory', memory, '--pids-limit', '1024',
            '--security-opt', 'no-new-privileges', '--user', f'{os.getuid()}:{os.getgid()}', '-w', '/workspace',
            '-e', 'HOME=/tmp/home', '-e', 'GIT_TERMINAL_PROMPT=0', '-e', 'GRADLE_USER_HOME=/cache/gradle',
            '-e', 'MAVEN_OPTS=' + AUDIT_MAVEN_OPTS,
            '-e', 'NUGET_PACKAGES=/cache/nuget', '-v', f'{root}:/workspace',
            '-v', f'{cache}:/cache', '-v', f'{root / target}:/workspace/{target}:ro',
            image, 'bash', '-lc', 'set -e\nmkdir -p /tmp/home\n' + command]
    started = time.monotonic()
    with (BUILD_SLOTS or threading.BoundedSemaphore(1)):
        with Path(log).open('w') as handle:
            proc = subprocess.Popen(args, stdout=handle, stderr=subprocess.STDOUT, start_new_session=True)
            try:
                code = proc.wait(timeout=timeout)
            except (subprocess.TimeoutExpired, KeyboardInterrupt):
                subprocess.run(['docker', 'rm', '-f', name], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                try:
                    os.killpg(proc.pid, signal.SIGTERM)
                except ProcessLookupError:
                    pass
                proc.wait(); code = None
    return {'exit_code': code, 'seconds': round(time.monotonic() - started, 2), 'log': str(log)}


def reset(root: Path, commit: str):
    for tail in (['reset', '--hard', commit], ['clean', '-fdx']):
        code, out, _ = run_process(['git', '-C', str(root), *tail], timeout=120)
        if code:
            raise RuntimeError('Cannot clean task checkout: ' + out[-500:])


def checked_target(root: Path, relative: str) -> Path:
    p = Path(safe_path(relative)); target = root / p
    if not target.is_file() or target.is_symlink() or not target.resolve().is_relative_to(root.resolve()):
        raise ValueError('Missing or escaping target')
    return target


def target_state(task: Task, target: Path):
    if source_digest(target) == task.file_after_sha256:
        return 'exact'
    after = Path(task.record_dir) / 'file_after.txt'
    if after.is_file() and lossy_text(after.read_bytes()) == lossy_text(target.read_bytes()):
        return 'lossy'
    return None


def restore_dataset_target(task: Task, target: Path):
    state = target_state(task, target)
    if state == 'lossy':
        target.write_bytes((Path(task.record_dir) / 'file_after.txt').read_bytes())
        if source_digest(target) != task.file_after_sha256:
            raise ValueError('Dataset file_after.txt does not hash to file_after_sha256')
    return state


def buggy_state(task: Task, target: Path):
    """Is the checked-out target the dataset's buggy file? 'exact', 'lossy' (same modulo
    undecodable bytes / keyword expansion) or None."""
    before = Path(task.record_dir) / 'file_before.txt'
    if task.file_before_sha256 and source_digest(target) == task.file_before_sha256:
        return 'exact'
    if before.is_file() and lossy_text(before.read_bytes()) == lossy_text(target.read_bytes()):
        return 'lossy'
    return None


def restore_buggy_target(task: Task, target: Path):
    """Put the dataset's buggy file in place: a no-op when the parent tree already has it; on the
    fixing commit (fix-commit environment) the tree holds the fixed file and the buggy one is
    written over it, exactly as the packaged task does."""
    state = buggy_state(task, target)
    if state == 'lossy' or (task.environment != 'parent' and state != 'exact'):
        target.write_bytes((Path(task.record_dir) / 'file_before.txt').read_bytes())
        state = state or 'written'
    return state


def diagnostics(output: str, target: str) -> list:
    """Compiler diagnostics at line 1 of the poisoned file: javac via Maven prints File.java:[1,5]
    or File.java:[1]; plain javac File.java:1:; csc/msbuild File.cs(1,5)."""
    name = re.escape(Path(target).name)
    pats = [name + r':(?:\[1(?:,\d+)?\]|1(?:[:,]))', name + r'\(1(?:,\d+)?\)']
    return [l for l in output.splitlines() if any(re.search(p, l) for p in pats)
            and re.search(r'error|expected|illegal|invalid|class, interface', l, re.I)]


def source_inventory(root: Path) -> dict:
    out = {}
    proc = subprocess.run(['git', '-C', str(root), 'ls-files', '-z'], capture_output=True, check=True)
    for item in proc.stdout.split(b'\0'):
        if not item:
            continue
        rel = os.fsdecode(item)
        if Path(rel).suffix in {'.cs', '.java', '.c', '.h', '.cpp', '.hpp'}:
            p = root / rel; out[rel] = hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None
    return out


SETTINGS_SECTIONS = ('mirrors', 'profiles', 'servers', 'pluginGroups', 'activeProfiles', 'proxies')


def merge_settings_sections(text: str) -> str:
    """Maven refuses a settings file that repeats a top-level section. Recipes build theirs by
    appending their own <profiles> to ours, which already has one, so the sections are merged."""
    for section in SETTINGS_SECTIONS:
        blocks = list(re.finditer(rf'<{section}>(.*?)</{section}>', text, re.S))
        if len(blocks) < 2:
            continue
        merged = f'<{section}>' + ''.join(b.group(1) for b in blocks) + f'</{section}>'
        for block in reversed(blocks[1:]):
            text = text[:block.start()] + text[block.end():]
        first = re.search(rf'<{section}>.*?</{section}>', text, re.S)
        text = text[:first.start()] + merged + text[first.end():]
    return text


def normalize_settings(cache: Path) -> list:
    """Repair settings files a recipe wrote into the shared cache. Returns the ones changed."""
    fixed = []
    for path in sorted((cache / 'm2').glob('*.xml')):
        try:
            text = path.read_text(errors='replace')
        except OSError:
            continue
        if '<settings' not in text[:400]:
            continue
        merged = merge_settings_sections(text)
        if merged != text:
            path.write_text(merged); fixed.append(path.name)
    return fixed


def validate(task: Task, root: Path, cache: Path, proposal: dict, work: Path, args) -> dict:
    """The proof: clean tree + setup + build of the fixed source must pass; the same with the
    target replaced by garbage must fail with a compiler error on line 1 of that file."""
    work.mkdir(parents=True, exist_ok=True)
    image = resolve_image(proposal.get('image'), task.language)
    try:
        identity = ensure_image(image, args.cache_dir, args.vendor_dir)
    except (ValueError, subprocess.TimeoutExpired) as e:
        rec = {'proposal': proposal, 'status': 'image_unavailable', 'error': str(e), 'stages': {}}; dump(work / 'result.json', rec); return rec
    proposal = dict(proposal, image=image)
    rec = {'proposal': proposal, 'image_id': identity, 'status': 'failed', 'stages': {}, 'environment': task.environment}
    initial = None
    # Files a setup step installs into the shared project cache must not leak into other
    # attempts' proof (a later recipe would pass only because an earlier one seeded the cache).
    cache_before = cache_files(cache)
    try:
        for phase in ('buggy', 'broken', 'fixed'):
            reset(root, base_commit(task))
            target = checked_target(root, task.target_file)
            state = restore_buggy_target(task, target)
            if state is None:
                raise ValueError('Buggy source identity mismatch after clean reset')
            if state == 'lossy':
                rec['target_source'] = 'dataset_file_before_lossy_encoding'
            elif state == 'written':
                rec['target_source'] = 'dataset_file_before_over_fixing_commit'
            expected = task.file_before_sha256
            if phase == 'fixed':
                # the upstream fix, dropped into the buggy tree: does a one-file fix exist?
                target.write_bytes((Path(task.record_dir) / 'file_after.txt').read_bytes())
                expected = task.file_after_sha256
            if initial is None:
                initial = source_inventory(root)
            setup = proposal.get('setup_shell', '') or ''
            if setup.strip():
                # Recipes build their settings by appending mirrors to ours. Setup runs once per
                # phase, so yesterday's (or this attempt's first) copy has to go first, or the
                # second run duplicates its blocks and Maven refuses the file.
                for stale in (cache / 'm2').glob('*.xml'):
                    if stale.name != 'audit-settings.xml':
                        stale.unlink(missing_ok=True)
                r = execute(root, task.target_file, cache, image, setup, work / f'{phase}-setup.log', args.build_timeout, args.cpus, args.memory)
                rec['stages'][phase + '_setup'] = r
                normalize_settings(cache)       # a recipe may have appended to a settings file of ours
                if r['exit_code'] != 0:
                    purge_broken_nuget(cache)   # an interrupted restore leaves packages half extracted
                if r['exit_code'] != 0:
                    rec['status'] = phase + '_setup_failed'; return rec
            if source_digest(target) != expected:
                raise ValueError('Preparation changed target source')
            # the file under test is written by the phases themselves (fix, poison); every other
            # source must be untouched unless the recipe declares itself a compatibility repair
            changed = sorted(k for k, v in source_inventory(root).items() if initial.get(k) != v and k != task.target_file)
            if changed:
                rec['support_source_changes'] = changed
                if proposal.get('classification') != 'compatibility':
                    rec['status'] = 'undeclared_source_changes'; return rec
            if phase == 'broken':
                target.write_bytes(POISON)
            r = execute(root, task.target_file, cache, image, proposal['build_shell'], work / f'{phase}.log', args.build_timeout, args.cpus, args.memory)
            rec['stages'][phase] = r
            if r['exit_code'] != 0:
                # A build that was killed or that died mid-restore leaves packages the next attempt
                # would read as "incompatible with this framework" (NU1202) forever after.
                for package in purge_broken_nuget(cache) + purge_packages_named_in(Path(r['log']), cache):
                    print(f'{task.task_id}: dropped {package}, damaged by a failed build', flush=True)
            if phase != 'broken' and source_digest(target) != expected:
                raise ValueError('Build changed target source')
            if phase == 'broken' and target.read_bytes() != POISON:
                raise ValueError('Build replaced corrupted target')
            if phase == 'buggy':
                rec['buggy_builds'] = r['exit_code'] == 0
                # The parent tree must build as the developer left it. On the fixing commit (the
                # fallback for a parent that never built) the buggy file may fail to compile - the
                # upstream fix then IS the port that makes it compile - as long as the fixed tree builds.
                if r['exit_code'] != 0 and task.environment == 'parent':
                    rec['status'] = 'buggy_failed'; return rec
            if phase == 'fixed':
                rec['fix_is_local'] = r['exit_code'] == 0   # informational in the parent environment
                if r['exit_code'] != 0 and not rec.get('buggy_builds'):
                    rec['status'] = 'neither_state_builds'; return rec
            if phase == 'broken':
                proof = diagnostics(Path(r['log']).read_text(errors='replace'), task.target_file)
                rec['target_diagnostics'] = proof[:20]
                if r['exit_code'] in (None, 0) or not proof:
                    rec['status'] = 'target_inclusion_unverified'; return rec
        after = sorted(k for k, v in source_inventory(root).items() if k != task.target_file and initial.get(k) != v)
        classification = proposal.get('classification')
        if after:   # the build itself rewrote tracked sources (version stamping): exactness unproven
            rec['support_source_changes'] = after; rec['build_modified_sources'] = after; classification = 'compatibility'
        rec['status'] = 'verified_compatibility' if classification == 'compatibility' else 'verified'
        rec['file_after_sha256'] = task.file_after_sha256; rec['method'] = 'clean_readonly_target_poison_v1'
        return rec
    finally:
        reset(root, base_commit(task))
        if not rec['status'].startswith('verified'):
            for p in cache_files(cache) - cache_before:
                # Only Maven's tree: a Maven artifact without the origin record (_remote.repositories)
                # was installed by the setup step and must not leak into the next attempt's proof.
                # NuGet packages carry no such record, and deleting their assemblies leaves a package
                # NuGet still considers installed (its .nupkg.metadata survives) but that has no
                # files - the "not compatible with this framework" failures came from exactly that.
                if 'm2' not in p.relative_to(cache).parts[:1]:
                    continue
                if not p.name.endswith(('.lastUpdated',)) and '_remote.repositories' not in p.name:
                    if not (p.parent / '_remote.repositories').exists() and p.suffix in ('.jar', '.pom'):
                        p.unlink(missing_ok=True)
        dump(work / 'result.json', rec)


# --------------------------------------------------------------------------- recipe variants
def target_module(checkout: Path, target: str) -> str:
    parts = Path(target).parts[:-1]
    for i in range(len(parts), 0, -1):
        rel = '/'.join(parts[:i])
        if (checkout / rel / 'pom.xml').is_file():
            return rel
    return ''


def recipe_variants(proposal: dict, task: Task, checkout: Path | None = None) -> list:
    """Deterministic, source-preserving variants of a saved recipe for this task."""
    build = proposal.get('build_shell') or ''; target = task.target_file
    name = target.split('/')[-1]
    is_test = '/src/test/' in target or '/test/' in target or name.startswith('Test') or \
        name.endswith(('Test.java', 'Tests.java', 'IT.java', 'Tests.cs', 'Test.cs'))
    out = []
    def add(new_build, note):
        if new_build != build and all(v['build_shell'] != new_build for v in out):
            v = dict(proposal); v['build_shell'] = new_build
            v['rationale'] = (proposal.get('rationale') or '')[:2000] + f' [variant: {note}]'; v['variant_of'] = build
            out.append(v)
    # The recipe as the task will ship it. A step that depends on the original history (fetching
    # the rest of it, asserting an ancestor) cannot run in a packaged task, and it often no longer
    # runs here either, so the shipped form is worth proving in its own right.
    shipped = {k: adapt_recipe(proposal.get(k) or '', task) for k in ('setup_shell', 'build_shell')}
    if (shipped['setup_shell'], shipped['build_shell']) != (proposal.get('setup_shell') or '', build):
        v = dict(proposal, **shipped)
        v['rationale'] = (proposal.get('rationale') or '')[:2000] + ' [variant: recipe as packaged]'
        v['variant_of'] = build
        out.append(v)
    if re.search(r'\bmvn\b|mvnw', build):
        if checkout and (checkout / 'pom.xml').is_file():
            module = target_module(checkout, target)
            m_pl = re.search(r'-pl\s+(\S+)', build); m_f = re.search(r'-f\s+(?:/workspace/)?(\S+?)/?pom\.xml', build)
            f_dir = (m_f.group(1) if m_f else '').strip('/'); f_dir = '' if f_dir in ('', '.', 'workspace') else f_dir
            selected = m_pl.group(1) if m_pl else f_dir
            owns = (selected == module) or (selected == '' and not m_f)
            if module and owns and f_dir == module and not m_pl:
                add(re.sub(r'\s+', ' ', re.sub(r'-f\s+\S+?pom\.xml', f'-f /workspace/pom.xml -pl {module} -am', build)).strip(),
                    f'module {module} through the root reactor')
            if module and not owns:
                nb = re.sub(r'-pl\s+\S+(\s+-am)?', '', build); nb = re.sub(r'-f\s+\S+?pom\.xml', '-f /workspace/pom.xml', nb)
                if '-f /workspace/pom.xml' not in nb:
                    nb = re.sub(r'(\bmvn\b|mvnw)', r'\1 -f /workspace/pom.xml', nb, count=1)
                nb = nb.replace('-f /workspace/pom.xml', f'-f /workspace/pom.xml -pl {module} -am', 1)
                add(re.sub(r'\s+', ' ', nb).strip(), f'target module {module} through the root reactor')
        if is_test and re.search(r'(?<![\w-])compile(?![\w-])', build) and 'test-compile' not in build:
            for v in list(out) + [proposal]:
                add(re.sub(r'(?<![\w-])compile(?![\w-])', 'test-compile', v['build_shell']), 'test source: compile -> test-compile')
        skips = (' -Dcheckstyle.skip=true -Denforcer.skip=true -Dmaven.javadoc.skip=true -Dlicense.skip=true -Drat.skip=true'
                 ' -Dspotbugs.skip=true -Dpmd.skip=true -Dfindbugs.skip=true -Dremoteresources.skip=true'
                 ' -Dmaven.remote-resources.skip=true -Dgpg.skip=true -Dmaven.source.skip=true -Dxml.skip=true'
                 ' -Dmaven.plugin.skip=true -Dmaven.gitcommitid.skip=true -Ddocbkx.skip=true -Dasciidoctor.skip=true'
                 ' -Dformatter.skip=true -Dimpsort.skip=true -Dspotless.check.skip=true -Dfmt.skip=true')
        if '-Dcheckstyle.skip' not in build:
            for v in list(out) + [proposal]:
                add(re.sub(r'(\bmvn\b|mvnw)', r'\1' + skips, v['build_shell'], count=1), 'skip lint/report plugins that run before javac')
        for v in [proposal] + list(out):
            b = v['build_shell']
            if re.search(r'(?<![\w:-])test-compile(?![\w-])', b):
                add(re.sub(r'(?<![\w:-])test-compile(?![\w-])', 'resources:resources compiler:compile resources:testResources compiler:testCompile', b), 'direct compiler goals (main+test)')
            elif re.search(r'(?<![\w:-])compile(?![\w-])', b):
                add(re.sub(r'(?<![\w:-])compile(?![\w-])', 'resources:resources compiler:compile', b), 'direct compiler goals')
    elif re.search(r'\bant\b', build):
        if is_test and checkout:
            m_bx = re.search(r'-f\s+(?:/workspace/)?(\S+\.xml)', build)
            bx = checkout / (m_bx.group(1) if m_bx else 'build.xml')
            if bx.is_file():
                for n in re.findall(r'<target\s+[^>]*name="([^"]+)"', bx.read_text(errors='replace')):
                    if re.search(r'test', n, re.I) and re.search(r'compile|build', n, re.I):
                        add(re.sub(r'\s+\S+\s*$', ' ' + n, build), f'test source: ant target {n}')
    elif re.search(r'\bgradle\b|gradlew', build):
        if is_test and 'compileJava' in build and 'compileTestJava' not in build:
            add(build.replace('compileJava', 'compileTestJava'), 'test source: compileJava -> compileTestJava')
        if 'checkstyle' not in build and '-x' not in build:
            add((out[0]['build_shell'] if out else build) + ' -x checkstyleMain -x checkstyleTest -x pmdMain -x pmdTest -x spotbugsMain -x javadoc', 'skip lint tasks')
    if re.search(r'\bdotnet\b|\bmsbuild\b', build) and 'nuget.config' not in build.lower():
        # A NuGet.config may point at a local package folder that only a packaging step creates;
        # an absent folder fails the restore outright, an empty one is just an empty source.
        prefix = ('for cfg in $(find /workspace -maxdepth 4 -iname nuget.config 2>/dev/null); do '
                  'sed -n \'s/.*<add[^>]*value="\\([^"]*\\)".*/\\1/p\' "$cfg" | while read -r src; do '
                  'case "$src" in *://*) continue;; /*) mkdir -p "$src";; *) mkdir -p "$(dirname "$cfg")/$src";; esac; '
                  'done; done 2>/dev/null || true\n')
        for v in [proposal] + list(out):
            add(prefix + v['build_shell'], 'create local NuGet package sources')
    if re.search(r'\bdotnet\b|\bmsbuild\b', build) and 'nuget.config' not in build.lower():
        # A feed a historical NuGet.config names may be gone altogether (NU1301: the service index
        # itself does not load), which no restore flag downgrades. Sources that do not answer are
        # dropped; the packages themselves are on nuget.org.
        drop = ('for cfg in $(find /workspace -maxdepth 4 -iname nuget.config 2>/dev/null); do '
                'grep -oE \'value="https?://[^"]+"\' "$cfg" | sed \'s/^value="//; s/"$//\' | sort -u | while read -r src; do '
                'curl -fsS --max-time 20 -o /dev/null "$src" || sed -i "\\|$src|d" "$cfg"; '
                'done; done 2>/dev/null || true\n')
        for v in [proposal] + list(out):
            add(drop + v['build_shell'], 'drop NuGet sources that no longer answer')
    if re.search(r'\bdotnet\b|\bmsbuild\b', build) and 'RestoreIgnoreFailedSources' not in build:
        # A historical NuGet.config often lists a feed that no longer answers; the packages
        # themselves are on nuget.org, so a failed source is a warning rather than the end.
        for v in [proposal] + list(out):
            add(re.sub(r'(\bdotnet\s+(?:build|restore|publish|msbuild)\b|\bmsbuild\b)',
                       r'\1 -p:RestoreIgnoreFailedSources=true', v['build_shell'], count=1), 'tolerate unreachable NuGet feeds')
    image = resolve_image(proposal.get('image'), task.language)
    if task.language == 'java' and image in JAVA_IMAGES:
        for other in JAVA_IMAGES:
            if other != image:
                w = dict(proposal); w['image'] = other; w['variant_of'] = build
                w['rationale'] = (proposal.get('rationale') or '')[:2000] + f' [variant: image {other}]'; out.append(w)
    return out


