def warning_audit_summary(args):
    root=Path(args.output);manifest=json.loads((root/'manifest.json').read_text());eligible=set(manifest['task_ids'])
    rows=[json.loads(p.read_text()) for p in sorted((root/'results').glob('*.json'))];rows=[r for r in rows if r['task_id'] in eligible]
    counts={'total_tasks':len(eligible),'finished_tasks':len(rows),'remaining_tasks':len(eligible)-len(rows),
            'categories':dict(collections.Counter(r['category'] for r in rows)),
            'languages':{lang:dict(collections.Counter(r['category'] for r in rows if r['language']==lang)) for lang in ('java','csharp')},
            'before_statuses':dict(collections.Counter(r.get('variants',{}).get('before',{}).get('status','not_run') for r in rows)),
            'after_statuses':dict(collections.Counter(r.get('variants',{}).get('after',{}).get('status','not_run') for r in rows)),
            'reproduced_before':sum(bool(r.get('variants',{}).get('before',{}).get('trace_matches')) for r in rows),
            'same_location_candidates_before':sum(bool(r.get('variants',{}).get('before',{}).get('location_candidates')) for r in rows),
            'references_with_introduced_warnings':sum(r.get('diff_counts',{}).get('introduced',0)>0 for r in rows)}
    (root/'summary.json').write_text(json.dumps(counts,indent=2)+'\n');print(json.dumps(counts,indent=2))


def warning_audit_select_retries(args):
    """Freeze retry eligibility only after the original array terminates."""
    source=Path(args.root);output=Path(args.output)
    original=json.loads((source/'manifest.json').read_text())
    selected={};completed=0
    for task in original['task_ids']:
        path=source/'results'/(task+'.json')
        if not path.exists():
            selected[task]='missing_original_result'
            continue
        row=json.loads(path.read_text());completed+=1
        if row.get('category')=='build_or_dependency_failure':
            selected[task]='build_or_dependency_failure'
        elif any(v.get('status') in ('capture_failed','capture_timeout') for v in row.get('variants',{}).values()):
            selected[task]='capture_failure_or_timeout'
    ids=sorted(selected)
    manifest=json.loads((output/'manifest.json').read_text())
    manifest.update(tasks=len(ids),task_ids=ids,selection_policy='all final build/dependency failures, capture failures/timeouts, and missing results',original_finished_tasks=completed)
    def save(name,text):
        partial=output/(name+'.partial');partial.write_text(text);partial.replace(output/name)
    save('retry-ids.txt',''.join(task+'\n' for task in ids))
    save('manifest.json',json.dumps(manifest,indent=2)+'\n')
    save('selection-report.json',json.dumps({'original_total':len(original['task_ids']),'original_finished':completed,'selected':len(ids),'reasons':dict(collections.Counter(selected.values())),'task_reasons':selected},indent=2)+'\n')
    jobs=json.loads((output/'jobs.json').read_text());jobs.update(tasks=len(ids),selection_finalized=True)
    save('jobs.json',json.dumps(jobs,indent=2)+'\n')
    print('Final retry selection:',len(ids),dict(collections.Counter(selected.values())),flush=True)


def warning_audit_main():
    parser=argparse.ArgumentParser(description='Historical Java/C# warning audit; does not modify the task verifier')
    parser.add_argument('--audit-warnings',choices=('prepare','run','summary','select-retries'),required=True)
    for name in ('root','output','inputs','scratch','images','infer','infersharp-engine','proxy-helper','ids','ids-file','vendor-cache','dependency-cache',
                 'legacy-infersharp','infersharp-release','fix-commit-ids','infer-label','before-commits','repository-cache'):parser.add_argument('--'+name)
    parser.add_argument('--infersharp-biabduction',action='store_true',help='run --legacy-infersharp (1.3) with biabduction instead of Pulse')
    parser.add_argument('--gold',action='store_true',help="audit 'after' as the task's snapshot with the fixed file, not the fixing commit")
    parser.add_argument('--shard',type=int,default=0);parser.add_argument('--shards',type=int,default=1)
    parser.add_argument('--workers',type=int,default=6);parser.add_argument('--timeout',type=int,default=5400)
    args=parser.parse_args()
    if args.audit_warnings=='select-retries':return warning_audit_select_retries(args)
    if args.audit_warnings=='prepare':return warning_audit_prepare(args)
    if args.audit_warnings=='summary':return warning_audit_summary(args)
    import sqlite3
    db=sqlite3.connect(args.inputs);ids=[x[0] for x in db.execute('SELECT id FROM tasks ORDER BY id')];db.close()
    if args.ids:ids=args.ids.split(',')
    if args.ids_file:ids=[line.strip() for line in Path(args.ids_file).read_text().splitlines() if line.strip()]
    ids=ids[args.shard::args.shards]
    concurrency_file = Path(args.output) / 'concurrency.json'
    if concurrency_file.exists():
        args.workers = int(json.loads(concurrency_file.read_text())['workers_per_shard'])
        if not 1 <= args.workers <= 12:
            raise ValueError('workers_per_shard must be between 1 and 12')
    print('Audit worker count:', args.workers, flush=True)
    with ThreadPoolExecutor(max_workers=args.workers) as pool:list(pool.map(lambda task_id:warning_audit_one(args,task_id),ids))


def main():
    global TOKEN, BUILD_SLOTS, CHECK_SLOTS
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    for name in ('input', 'output', 'cache-dir'):
        ap.add_argument('--' + name, type=Path, required=(name == 'cache-dir' or '--embed-verified' not in sys.argv))
    for name in ('matches', 'repositories', 'recipes', 'vendor-dir', 'inferredbugs-root', 'token-file', 'scratch-dir'):
        ap.add_argument('--' + name, type=Path)
    ap.add_argument('--cached-only', action='store_true', help='Never run matching or repository resolution; use supplied caches')
    ap.add_argument('--limit', type=int, help='Maximum candidates to package; other rows remain unchanged')
    ap.add_argument('--task', action='append', default=[], help='Only these TaskTrove task ids')
    ap.add_argument('--tasks-file', type=Path, help='File with one TaskTrove task id per line (added to --task)')
    ap.add_argument('--dependency-dir', type=Path,
                    help='Where per-project dependency caches are built (default: <cache-dir>/dependencies); '
                         'a local disk is safer than a network mount under parallel writes')
    ap.add_argument('--prune-project-cache', action='store_true',
                    help="Delete a project's dependency cache once all its selected tasks are done")
    ap.add_argument('--check-slots', type=int, default=0,
                    help='Concurrent packaged checks (each starts with a clone GitHub may throttle); default: a quarter of the build slots')
    ap.add_argument('--build-timeout', type=int, default=5400,
                    help='Seconds for one validation build; a cold dependency download needs far more than a warm one')
    ap.add_argument('--verify-timeout', type=int, default=5400, help='Per step budget in the packaged verifier (cold dependency cache: downloads everything)'); ap.add_argument('--cpus', type=int, default=2); ap.add_argument('--memory', default='4g')
    ap.add_argument('--workers', type=int, default=1, help='Concurrent tasks'); ap.add_argument('--build-slots', type=int, help='Concurrent builds (default: workers)')
    ap.add_argument('--rematch', action='store_true',
                    help='Redo matching and repository resolution instead of using the facts embedded in the recipe table')
    ap.add_argument('--embed-verified', action='store_true',
                    help='Fold <cache-dir>/verified (a finished run) into EMBEDDED_RECIPES of this file, then exit')
    ap.add_argument('--trust-recipes', action='store_true',
                    help='Package from the embedded recipe table without re-proving it (no Docker, no caches); '
                         'the table was proven by a full cold run of this script')
    ap.add_argument('--no-verify-package', dest='verify_package', action='store_false',
                    help='Skip running the packaged verifier (fresh cache) with the original fixed file; on by default because it is the only check immune to cache contamination')
    ap.add_argument('--artifact-source', action='append', default=[], help='Local Maven cache tree(s) to take missing artifacts from when a packaged build cannot resolve them')
    ap.add_argument('--vendor-additions', type=Path, help='JSON file recording artifacts added by that healing (default: <cache-dir>/vendor_additions.json)')
    ap.add_argument('--repository-overrides', type=Path, help='JSON file of task -> repository recovered after a checkout failure (default: <cache-dir>/repository_overrides.json)')
    ap.add_argument('--no-recover-repositories', dest='recover_repositories', action='store_false', help='Do not search GitHub for a repository still serving a vanished commit')
    ap.add_argument('--vendor-repo', help='Hugging Face dataset receiving newly vendored artifacts (default: derived from --vendor-url)')
    ap.add_argument('--no-vendor-upload', action='store_true', help='Do not publish newly vendored artifacts to the vendor dataset')
    ap.add_argument('--heal-attempts', type=int, default=4, help='How often to vendor missing artifacts and retry the packaged check')
    ap.add_argument('--vendor-url', default=DEFAULT_VENDOR_URL,
                    help='Base URL serving vendored artifacts by SHA-256 (default: the public dataset); pass an empty string to ship them inside each task instead')
    ap.add_argument('--maven-proxy', help='Local read-through proxy base URL for validation builds (e.g. http://172.17.0.1:8081); packaged tasks always use public hosts')
    ap.add_argument('--repair-backend', choices=['none', 'claude', 'deepseek'], default='none')
    ap.add_argument('--repair-model'); ap.add_argument('--repair-effort', choices=['low', 'medium', 'high', 'xhigh', 'max'])
    ap.add_argument('--repair-attempts', type=int, default=2); ap.add_argument('--repair-workers', type=int, default=4)
    ap.add_argument('--repair-timeout', type=int, default=1800); ap.add_argument('--repair-budget-usd', type=float, default=3.0)
    ap.add_argument('--repair-spend-cap-usd', type=float)
    ap.add_argument('--reuse-failures', action='store_true',
                    help='Treat a cached failed attempt as final instead of retrying it')
    ap.add_argument('--verify-only', action='store_true', help='Only find and prove recipes (cache/verified/*.json); do not package or write the parquet')
    ap.add_argument('--print-prompts', action='store_true')
    ap.add_argument('--max-verify-seconds', type=int, default=300, help='Leave out tasks whose measured build plus analysis takes longer '
                    '(warning_identity/verification-times.json; default 300: keeps 96%% of the tasks, and a verification stays within minutes)')
    a = ap.parse_args()
    if a.print_prompts:
        print('=== BASE PROMPT ===\n' + BASE_PROMPT + '\n=== SANDBOX ADDENDUM (when --repair-backend != none) ===' + SANDBOX_PROMPT + '\n=== CLOSING ===' + CLOSING); return
    if a.embed_verified:
        a.vendor_additions = a.vendor_additions or a.cache_dir / 'vendor_additions.json'
        embed_verified(a); return
    if a.workers < 1 or a.input.resolve() == a.output.resolve():
        ap.error('--workers must be positive and output must differ from input')
    if a.tasks_file:
        a.task = list(a.task) + [l.strip() for l in a.tasks_file.read_text().splitlines() if l.strip()]
    TOKEN = github_token(a)
    slots = a.build_slots or a.workers
    try:   # each build gets --memory; more concurrent builds than RAM allows gets them OOM-killed
        total_gb = os.sysconf('SC_PAGE_SIZE') * os.sysconf('SC_PHYS_PAGES') / 1024 ** 3
        per_gb = float(re.sub(r'[^0-9.]', '', a.memory) or 4) * (1 / 1024 if a.memory.lower().endswith('m') else 1)
        affordable = max(1, int(total_gb * 0.8 / max(per_gb, 0.25)))
        if slots > affordable:
            print(f'NOTE limiting concurrent builds {slots} -> {affordable} ({total_gb:.0f} GiB RAM, {per_gb:g} GiB per build)', flush=True)
            slots = affordable
    except (ValueError, OSError):
        pass
    BUILD_SLOTS = threading.BoundedSemaphore(slots)
    CHECK_SLOTS = threading.BoundedSemaphore(a.check_slots or max(4, slots // 4))
    cache = a.cache_dir; cache.mkdir(parents=True, exist_ok=True)
    if a.scratch_dir:
        a.scratch_dir.mkdir(parents=True, exist_ok=True)
    # One run per cache directory: concurrent runs race on the shared per-project dependency caches.
    run_lock = (cache / 'run.lock').open('a')
    try:
        fcntl.flock(run_lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        ap.error(f'another run already holds {cache}/run.lock')
    manifest = cache / 'input.json'; identity = {'sha256': sha(a.input), 'source_commit': SOURCE_COMMIT}
    if manifest.exists() and json.loads(manifest.read_text()) != identity:
        ap.error('Cache belongs to a different input dataset; use another cache directory')
    manifest.write_text(json.dumps(identity))
    # 0. --trust-recipes: the embedded table already names every task's record, repository,
    #    commit and target, so neither matching nor repository resolution is needed - only the
    #    InferredBugs dataset itself (for the buggy file), fetched at its pinned commit if absent.
    # Matching and repository resolution are how the table was BUILT; their result (record, repository,
    # commit, target per task) is embedded, so they only run again on request (--rematch) or when
    # resolution files are passed explicitly.
    from_table = not a.rematch and not a.matches and not a.repositories
    if from_table:
        source = a.inferredbugs_root or cache / 'source'
        if not (source / 'inferredbugs').is_dir():
            print(f'fetching microsoft/InferredBugs at {SOURCE_COMMIT[:12]} into {source}', flush=True)
            source.mkdir(parents=True, exist_ok=True)
            subprocess.run(['git', 'init', '-q', str(source)], check=True)
            subprocess.run(['git', '-C', str(source), 'remote', 'add', 'origin', 'https://github.com/microsoft/InferredBugs.git'], check=True)
            subprocess.run(['git', '-C', str(source), 'fetch', '-q', '--depth=1', 'origin', SOURCE_COMMIT], check=True)
            subprocess.run(['git', '-C', str(source), 'checkout', '-q', '--detach', 'FETCH_HEAD'], check=True)
        if subprocess.check_output(['git', '-C', str(source), 'rev-parse', 'HEAD'], text=True).strip() != SOURCE_COMMIT:
            ap.error('Original InferredBugs checkout is not at the pinned commit')
        projects = collections.defaultdict(list)
        for row in embedded_recipes():
            if not row.get('commit'):
                continue
            record_dir = source / 'inferredbugs' / row['language'] / row['project'] / str(row['bug_id'])
            projects[(row['language'], row['project'])].append(Task(
                row['task_id'], row['language'], row['project'], str(row['bug_id']), record_dir,
                row['commit'], row['target_file'], row['file_after_sha256'], row['repository'],
                file_before_sha256=row.get('file_before_sha256') or source_digest(record_dir / 'file_before.txt'),
                parent=row.get('parent') or ''))
        tasks = {t.task_id: t for ts in projects.values() for t in ts}
        print(f'trusting the embedded table: {len(tasks)} tasks in {len(projects)} projects', flush=True)
        matches = []
    # 1. matching
    matches_path = cache / 'matches.jsonl'
    if a.matches and a.matches.resolve() != matches_path.resolve():
        shutil.copyfile(a.matches, matches_path)
    if from_table:
        pass
    elif not matches_path.exists():
        if a.cached_only:
            ap.error('Matching cache missing')
        source = a.inferredbugs_root or cache / 'source'
        if not source.exists():
            subprocess.run(['git', 'clone', 'https://github.com/microsoft/InferredBugs.git', str(source)], check=True)
            subprocess.run(['git', '-C', str(source), 'checkout', '--detach', SOURCE_COMMIT], check=True)
        if subprocess.check_output(['git', '-C', str(source), 'rev-parse', 'HEAD'], text=True).strip() != SOURCE_COMMIT:
            ap.error('Original InferredBugs checkout is not at the pinned commit')
        matches_path.write_text(''.join(json.dumps(m, ensure_ascii=False) + '\n' for m in match_dataset(a.input, source)))
    if not from_table:
        matches = records(matches_path)
    # 2. repository resolution
    repositories = cache / 'repositories.jsonl'
    if a.repositories and a.repositories.resolve() != repositories.resolve():
        rows = {(r['language'], r['project']): r for r in records(a.repositories)}
        for r in records(repositories):
            if r.get('schema_version') == 2 or (r['language'], r['project']) not in rows:
                rows[(r['language'], r['project'])] = r
        repositories.write_text(''.join(json.dumps(r) + '\n' for r in rows.values()))
    if from_table:
        pass
    elif not a.cached_only:
        resolve_all(matches, repositories, cache / 'github', TOKEN)
    elif not repositories.exists():
        ap.error('Repository cache missing')
    if not from_table:
        projects = load_tasks(matches, repositories)
        tasks = {t.task_id: t for ts in projects.values() for t in ts}
        # reproducibility report: what a fresh derivation says versus what the table remembers
        embedded = {r['task_id']: r for r in embedded_recipes() if r.get('commit')}
        differ = collections.Counter()
        for tid, t in tasks.items():
            e = embedded.get(tid)
            if not e:
                differ['not in table'] += 1; continue
            for field, value in (('commit', t.commit), ('target_file', t.target_file),
                                 ('file_after_sha256', t.file_after_sha256), ('repository', t.repository)):
                if e.get(field) != value:
                    differ[field] += 1
        differ['not resolved now'] = len(embedded) - len([t for t in tasks if t in embedded])
        print(f'rematch: {len(tasks)} tasks derived fresh; disagreements with the embedded table: {dict(differ)}', flush=True)
    # 3. recipes
    table, project_recipes = load_recipes(a.recipes)
    if a.vendor_additions is None:
        a.vendor_additions = cache / 'vendor_additions.json'
    if a.repository_overrides is None:
        a.repository_overrides = cache / 'repository_overrides.json'
    overrides = json.loads(a.repository_overrides.read_text()) if a.repository_overrides.exists() else {}
    if overrides:
        for group in projects.values():
            for index, task in enumerate(group):
                if task.task_id in overrides and task.repository != overrides[task.task_id]:
                    group[index] = replace(task, repository=overrides[task.task_id])
        tasks = {t.task_id: t for ts in projects.values() for t in ts}
        print(f'applied {len(overrides)} recovered repository mappings', flush=True)
    for task_id, extra in (json.loads(a.vendor_additions.read_text()) if a.vendor_additions.exists() else {}).items():
        row = table.get(task_id)
        if row is not None:
            have = {x['path'] for x in row['non_central_artifacts']}
            row['non_central_artifacts'] += [x for x in extra if x['path'] not in have]
    print(f'tasks with a resolved repository: {len(tasks)}; recipe rows: {len(table)}; projects with recipes: {len(project_recipes)}', flush=True)
    sync_vendor_repo(a)   # a packaged task can only fetch what the vendor dataset actually holds
    repairer = Repairer(a)
    a.output.parent.mkdir(parents=True, exist_ok=True)
    parquet = pq.ParquetFile(a.input); temporary = a.output.with_suffix('.partial.parquet')
    # Phase 1: select tasks and validate/package them, projects in parallel, tasks of one
    # project sequentially (they share a dependency cache). Results are cached on disk.
    statuses = {}; selected = collections.defaultdict(list); attempted = 0
    for batch in parquet.iter_batches(batch_size=256, columns=['path']):
        for name in batch.column('path').to_pylist():
            if name not in tasks:
                statuses[name] = 'unchanged_no_resolved_repository'
            elif a.task and name not in a.task:
                statuses[name] = 'unchanged_not_selected'
            elif a.limit is not None and attempted >= a.limit:
                statuses[name] = 'unchanged_limit'
            else:
                attempted += 1; t = tasks[name]; selected[(t.language, t.project)].append(name)
    wanted = set() if a.verify_only else {n for names in selected.values() for n in names}
    originals = {}
    for batch in ([] if a.verify_only else parquet.iter_batches(batch_size=256)):
        for row in batch.to_pylist():
            if row['path'] in wanted:
                originals[row['path']] = row['task_binary']
    # Phase 0: packaged re-checks are independent of the shared project cache, so they run
    # fully in parallel instead of behind each project's serial task queue.
    stale = []
    for key, names in selected.items():
        for name in names:
            record_path = cache / 'verified' / f'{verification_key(tasks[name], table.get(name), a)}.json'
            if record_path.exists() and needs_recheck(json.loads(record_path.read_text()), a):
                stale.append((name, key, record_path))
    if stale:
        print(f'rechecking {len(stale)} tasks packaged under an older layout', flush=True)
        progress = [0]; plock = threading.Lock()
        def recheck_one(item):
            name, key, record_path = item
            try:
                record = _recheck(a, tasks[name], table.get(name), json.loads(record_path.read_text()), record_path)
                state = record.get('status')
            except (ValueError, OSError, RuntimeError, subprocess.SubprocessError) as e:
                state = f'recheck_error: {e}'
            with plock:
                progress[0] += 1
                print(f'recheck {name} {state} [{progress[0]}/{len(stale)}]', flush=True)
        with ThreadPoolExecutor(max_workers=a.build_slots or a.workers) as pool:
            for f in [pool.submit(recheck_one, item) for item in stale]:
                f.result()
    patched = {}; done = [0]; lock = threading.Lock()
    def run_project(key, names):
        for name in names:
            task = tasks[name]
            try:
                if a.verify_only:
                    rec = verify_task(a, cache, task, table.get(name), project_recipes.get(key, []), repairer)
                    if not str(rec.get('status', '')).startswith('verified'):
                        raise ValueError(f'{rec.get("status")}; evidence in {rec.get("evidence")}')
                    blob = None; status = 'verified'
                    if (rec.get('proposal') or {}).get('environment', 'parent') != 'parent':
                        status += ' on-fixing-commit (parent tree never built)'
                else:
                    blob = candidate(a, cache, task, unpack(originals[name]), table.get(name), project_recipes.get(key, []), repairer)
                    status = 'patched'
            except (ValueError, OSError, RuntimeError, subprocess.SubprocessError) as e:
                blob = None; status = 'unchanged_validation_failed: ' + str(e)
                print(f'WARNING {name} ({task.language}/{task.project}) dropped: {e}', file=sys.stderr, flush=True)
            with lock:
                statuses[name] = status
                if blob is not None:
                    patched[name] = blob
                originals.pop(name, None); done[0] += 1
                print(f'{name} {status} [{done[0]}/{attempted}]', flush=True)
        if a.prune_project_cache:
            # Every task of this project is done; its dependency cache is worth nothing now, and
            # keeping 1300 of them would need more disk than the dataset itself.
            shutil.rmtree(dependency_root(a, cache) / key[0] / key[1], ignore_errors=True)
    print(f'selected {attempted} tasks in {len(selected)} projects', flush=True)
    with ThreadPoolExecutor(max_workers=a.workers) as pool:
        # biggest projects first so the long sequential chains start early
        futures = [pool.submit(run_project, key, names) for key, names in sorted(selected.items(), key=lambda kv: -len(kv[1]))]
        for f in futures:
            f.result()
    if a.verify_only:
        c = collections.Counter(v.split(':')[0] for v in statuses.values())
        print(json.dumps(dict(c), indent=2)); return
    # Phase 2: write the output parquet in input order; unpatched rows stay byte-for-byte.
    report = []
    with pq.ParquetWriter(temporary, parquet.schema_arrow) as writer:
        for batch in parquet.iter_batches(batch_size=256):
            rows = batch.to_pylist()
            kept = []
            for row in rows:
                if row['path'] in DISCARDED:
                    report.append({'task': row['path'], 'status': 'discarded: ' + DISCARDED[row['path']]})
                    continue
                times = verification_times(row['path'])
                if a.max_verify_seconds and times and times['build'] + times['analyze'] > a.max_verify_seconds:
                    report.append({'task': row['path'], 'status': 'discarded: verification_too_slow'})
                    continue
                if row['path'] in patched:
                    row['task_binary'] = patched[row['path']]
                report.append({'task': row['path'], 'status': statuses.get(row['path'], 'unchanged')})
                kept.append(row)
            writer.write_table(pa.Table.from_pylist(kept, schema=parquet.schema_arrow))
    temporary.replace(a.output)
    a.output.with_suffix('.report.json').write_text(json.dumps(report, indent=2))
    print(json.dumps(dict(collections.Counter(r['status'].split(':')[0] for r in report)), indent=2))
    if repairer.spend:
        print(f'agent spend: {repairer.spend:.2f} USD')


# The static analyzer of each task, pinned to the release whose output matches the task's historical
# warning. Java: Infer 0.17.0 unless JAVA_INFER names another release; 0.16/0.17 need Python 2.7 for
# their capture. C#: the InferSharp release named in CSHARP_INFERSHARP (default 1.3): the dataset was
# mined with several; 1.2 reports biabduction NULL_DEREFERENCE, 1.3 the Pulse-based DOTNET_RESOURCE_LEAK
# and NULLPTR_DEREFERENCE with the dataset's wording ('1.3 biabduction': the same release run with
# its biabduction checker), 1.5 PULSE_UNINITIALIZED_VALUE.
# The analyzer is not part of the task image (the images stay the eight shared ones): every task
# ships install_analyzer.sh, which the agent may run and the verifier always runs itself.
ANALYZERS = {
    'Infer 0.16.0': '435c415a9a22f41e7f2074b542b035b972a2a8c237d5490285d763bf333a817b',
    'Infer 0.17.0': 'de972ba3043f18b29a8eff6cd7612e24f5ffaef038dc7949befeaf490931725e',
    'Infer 1.0.0': '510eeccc7e6bcc2678ac92a88f8e1cb9c07c3e14d272dcc06834e93845bb120f',
    'Infer 1.1.0': '5f5d453814422e93e2a70998d8946b09a2721628ff427f67ff0123dea87461d4',
    'InferSharp 1.2': '58c85bd7d82b7be205cefb0c90de0e63d0df041e63442c80407b74dea0e46975',
    'InferSharp 1.3': '77da740fb8859bef530335b0da30a59aa543b161d49853ed23e41bd85477718e',
    'InferSharp 1.4': 'fb5d473cc8e8d9a3125edabaa9c0992fb3261d2e9fbd31b891f67ce6f752e936',
    'InferSharp 1.5': 'c0f36ffb7515e83f2968e4e7c4d669c3bba1d90a1188fdd0c1413378adb75d92',
}
_INSTALL_HEAD = r'''#!/bin/bash
# Generated by patch_tasktrove_inferredbugs_v3.py.
# Installs {analyzer}, the static analyzer that reports this task's warning, into /opt
# (needs root and network access). Every download is checked against its SHA-256.
# Usage: bash install_analyzer.sh [--force]     --force reinstalls from scratch
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
STAMP=/opt/inferredbugs-analyzer
if [ "${{1:-}}" != --force ] && [ "$(cat "$STAMP" 2>/dev/null)" = "{analyzer}" ]; then
  echo "{analyzer} is already installed"; exit 0
fi
rm -rf "$STAMP" /opt/infer /opt/infersharp /usr/local/bin/infer
fetch() {{   # URL SHA256 FILE
  local attempt
  # INFERREDBUGS_DOWNLOAD_CACHE: a directory of files named by their SHA-256 (see warmup.py)
  if [ -n "${{INFERREDBUGS_DOWNLOAD_CACHE:-}}" ] && [ -f "$INFERREDBUGS_DOWNLOAD_CACHE/$2" ]; then cp "$INFERREDBUGS_DOWNLOAD_CACHE/$2" "$3" && return 0; fi
  for attempt in 1 2 3 4 5; do
    if curl -fLsS --retry 3 --connect-timeout 20 "$1" -o "$3" && echo "$2  $3" | sha256sum -c --quiet -; then return 0; fi
    sleep $((attempt * 10 + RANDOM % 10))
  done
  echo "cannot download $1" >&2; return 1
}}
packages() {{
  # apt downloads as a second user into directories the image made for that user. A container
  # that maps a single user (apptainer --fakeroot) has no such user and cannot write there:
  # download as root into directories of our own.
  local apt="apt-get -o APT::Sandbox::User=root -o Dir::Cache::Archives=$work/apt/archives -o Dir::State::Lists=$work/apt/lists"
  mkdir -p "$work/apt/archives/partial" "$work/apt/lists/partial"
  $apt update >/dev/null && $apt install -y --no-install-recommends "$@" >/dev/null
}}
work=$(mktemp -d); trap 'rm -rf "$work"' EXIT
'''
_INSTALL_PYTHON2 = r'''# The capture of this Infer release is written in Python 2.7, which the Java images carry.
[ -x /opt/python2/bin/python2.7 ] || { echo "Python 2.7 is missing: this analyzer runs on the task's Java image" >&2; exit 1; }
'''
_INSTALL_INFER = r'''command -v xz >/dev/null || packages xz-utils
fetch https://github.com/facebook/infer/releases/download/v{version}/infer-linux64-v{version}.tar.xz {sha256} "$work/infer.tar.xz"
mkdir -p /opt/infer && tar -xJf "$work/infer.tar.xz" --strip-components=1 -C /opt/infer
printf '#!/bin/sh\nPATH=/opt/python2/bin:/opt/infer/bin:$PATH exec /opt/infer/bin/infer "$@"\n' > /usr/local/bin/infer && chmod +x /usr/local/bin/infer
/opt/infer/bin/infer --version | head -1
'''
_INSTALL_INFERSHARP = r'''# Its Infer needs a time zone database (without one, capture aborts formatting the run time).
[ -d /usr/share/zoneinfo ] || packages tzdata
fetch https://github.com/microsoft/infersharp/releases/download/v{version}/infersharp-linux64-v{version}.tar.gz {sha256} "$work/infersharp.tgz"
tar -xzf "$work/infersharp.tgz" -C /opt && echo {version} > /opt/infersharp/VERSION
/opt/infersharp/infer/lib/infer/infer/bin/infer --version | head -1
'''
# Cilsil, the translator of InferSharp 1.2 and 1.3, runs on .NET 5 (1.4 and 1.5: .NET 6, which
# takes OpenSSL 3). That runtime loads OpenSSL 1.x
# as soon as an assembly makes it hash or verify something, and aborts without it ("No usable
# version of libssl was found"); the Debian 12 images carry only OpenSSL 3. The two libraries come
# from Debian 11's package, by hash (LIBSSL1), and are only added: nothing of the image is replaced.
LIBSSL1 = ('https://snapshot.debian.org/archive/debian/20231003T205808Z/pool/main/o/openssl/libssl1.1_1.1.1w-0+deb11u1_amd64.deb',
           'aadf8b4b197335645b230c2839b4517aa444fd2e8f434e5438c48a18857988f7')
_INSTALL_LIBSSL1 = r'''# Its translator runs on .NET 5, which needs OpenSSL 1.x (this image has only OpenSSL 3).
if ! ls /usr/lib/x86_64-linux-gnu/libssl.so.1.* /usr/lib64/libssl.so.1.* >/dev/null 2>&1; then
  fetch {url} {sha256} "$work/libssl1.1.deb"
  dpkg-deb -x "$work/libssl1.1.deb" "$work/libssl1.1"
  mkdir -p /usr/lib/x86_64-linux-gnu
  cp -a "$work/libssl1.1/usr/lib/x86_64-linux-gnu/libssl.so.1.1" "$work/libssl1.1/usr/lib/x86_64-linux-gnu/libcrypto.so.1.1" /usr/lib/x86_64-linux-gnu/
fi
'''


def analyzer_release(analyzer: str) -> str:
    """'InferSharp 1.3 biabduction' is release 'InferSharp 1.3' with another checker."""
    return ' '.join(analyzer.split()[:2])


def install_analyzer_script(analyzer: str) -> bytes:
    release = analyzer_release(analyzer)
    kind, version = release.split()
    body = _INSTALL_HEAD.format(analyzer=release)
    if kind == 'Infer':
        body += (_INSTALL_PYTHON2 if version.startswith('0.') else '') + _INSTALL_INFER.format(version=version, sha256=ANALYZERS[release])
    else:
        body += _INSTALL_INFERSHARP.format(version=version, sha256=ANALYZERS[release])
        if tuple(map(int, version.split('.'))) < (1, 4):
            body += _INSTALL_LIBSSL1.format(url=LIBSSL1[0], sha256=LIBSSL1[1])
    return (body + 'echo "' + release + '" > "$STAMP"\n').encode()


